actions.script:
canEdit = ec.user.hasPermission('MONITOR_EVAL')
const num = v => v == null ? null : v.toNumber ? v.toNumber() : Number(v)
const find = (n, c) => ec.entity.find(n).condition(c).disableAuthz()
const json = t => { try { return JSON.parse(t) } catch (e) { return null } }
const clip = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(0, n) + '…' : t }
const scorers = {}; for (const s of find('moqui.agent.AgentScorer', {}).list()) scorers[s.scorerId] = s
scorerOptions = Object.values(scorers).filter(s => s.scorerTypeEnumId !== 'AgstHuman').map(s => ({value: s.scorerId, label: s.scorerName || s.scorerId}))
datasetOptions = Array.from(find('moqui.agent.AgentDataset', {}).list()).map(d => ({value: d.datasetId, label: d.datasetName || d.datasetId}))
agentOptions = Array.from(find('moqui.agent.AgentDefinition', {}).list()).map(a => ({value: a.agentId, label: a.agentName || a.agentId}))
let runs
if (scoredOnly === 'Y') {
    const ids = [...new Set(Array.from(find('moqui.agent.AgentScore', {}).orderBy('-scoredDate').limit(300).list()).map(s => s.runId).filter(Boolean))].slice(0, 100)
    runs = ids.map(id => find('moqui.agent.AgentRun', {runId: id}).one()).filter(r => r && (!agentId || r.agentId === agentId))
} else {
    const c = {}; if (runId) c.runId = runId; if (agentId) c.agentId = agentId
    runs = Array.from(find('moqui.agent.AgentRun', c).orderBy('-submittedDate').limit(50).list())
}
runRows = runs.map(r => {
    // the run's user message, else the conversation's last one sent by the time the run was submitted (external runs)
    const at = r.submittedDate == null ? Infinity : Date.parse(String(r.submittedDate)) || Number(String(r.submittedDate))
    const msg = Array.from(find('moqui.agent.AgentMessage', {runId: r.runId, role: 'user'}).orderBy('messageSeq').limit(1).list())[0]
        || (r.conversationId ? Array.from(find('moqui.agent.AgentMessage', {conversationId: r.conversationId, role: 'user'}).orderBy('-messageSeq').limit(20).list()).find(m => (Date.parse(String(m.createdDate)) || Number(String(m.createdDate)) || 0) <= at + 1000) : null)
    const input = msg ? Array.from(find('moqui.agent.AgentMessagePart', {messageId: msg.messageId}).orderBy('partSeq').list()).filter(p => p.partKindEnumId === 'AgpkText').map(p => p.textValue).join('\n') : ''
    const result = json(r.resultJson), output = result?.text ?? result?.output ?? (result && typeof result == 'object' ? JSON.stringify(result) : r.resultJson) ?? r.errorText
    const scores = Array.from(find('moqui.agent.AgentScore', {runId: r.runId}).orderBy('-scoredDate').list())
    return {runId: r.runId, agentId: r.agentId || (r.externalHarnessId ? 'external ' + r.externalHarnessId : ''), statusId: r.statusId, endedDate: r.endedDate == null ? '' : ec.l10n.format(r.endedDate, 'yyyy-MM-dd HH:mm'), cost: r.cost, input: clip(input, 300), output: clip(output, 500),
        scores: scores.map(s => (scorers[s.scorerId]?.scorerName || s.scorerId) + ' (' + String(s.sourceEnumId || '').replace('Agss', '').toLowerCase() + '): ' + (s.score == null ? 'error' : num(s.score).toFixed(2)) + (s.reason ? ' — ' + clip(s.reason, 140) : '')).join('\n')}
})
